import {expectationsSource} from './planning-expectations-data.js';
export const expectationsDefinitions={expectations:{title:'Read the survey, then test an independently entered price scenario',fields:[
 ['expectCost','Annual cost in current CAD for the independent scenario',12000,0,50000,1000],
 ['expectInflation','Independent assumed annual price growth (%)',3,0,8,.5],
 ['expectYears','Years to the independent scenario’s future annual cost',10,1,30,1]
]}};
export function expectationPriceScenario(i){
 return Array.from({length:i.expectYears+1},(_,x)=>({x,current:i.expectCost,future:i.expectCost*(1+i.expectInflation/100)**x}));
}
const horizonSeries=[['CES_C1_SHORT_TERM','1-year ahead'],['CES_C1_MID_TERM','2-year ahead'],['CES_C1_LONG_TERM','5-year ahead']];
export function expectationsResult(kind,i){
 if(kind!=='expectations')throw Error('Unknown expectations topic.');
 const observations=expectationsSource.rows,last=observations.at(-1),prior=observations.at(-2),plan=expectationPriceScenario(i);
 const source={source:expectationsSource.reportUrl,sourceLabel:'Bank of Canada · CSCE 2026 Q3 and linked Valet data'};
 const series=(name,key,dash=false)=>({name,dash,rows:plan.map(r=>({x:r.x,value:r[key]}))});
 return {metrics:[['2026 Q3 · 1-year-ahead interpolated median',last.CES_C1_SHORT_TERM/100,'percent'],['2026 Q3 · 5-year-ahead interpolated median',last.CES_C1_LONG_TERM/100,'percent'],['Independent scenario · future annual cost',plan.at(-1).future,'money']],note:'The first three charts use published CSCE interpolated medians from the Bank of Canada’s 19 October 2026 release and its linked quarterly data group, retrieved 25 October 2026. The online survey was collected 5–27 August 2026; follow-up interviews ran 24 August–4 September. Quarterly data keys mark the start of the reference quarter, not an interview or release date. The data summarize respondent perceptions and expectations; they are not actual CPI observations or the Bank’s own inflation forecast. Eight quarters from 2024 Q4 to 2026 Q3 are retained. No respondent-level data, sampling interval or significance test is supplied here. The final two charts are separate hypothetical annual-cost scenarios. Their price-growth input is independent of every survey observation, is applied once per complete year, and is held constant solely for the exercise. The displayed future cost is an annual amount at that date, not cumulative spending, present value, savings required or a promised bill. No income, investment return, tax, fee or payment account is calculated.',charts:[
  {...source,id:'expectations-latest-horizons',type:'bar',evidence:'Official survey results',title:'The latest survey separates perceived past inflation from future expectations',unit:'percent',unitLabel:'2026 Q3 · interpolated median (%) · distinct questions',rows:[
   {label:'Perceived rate over the past 12 months',value:last.CES_C1_PERCEPTIONS/100},
   ...horizonSeries.map(([key,label])=>({label:label+' expectation',value:last[key]/100}))
  ],note:'The perception row is a survey answer about the past, not a measured CPI rate. The other rows retain the published horizon labels. These medians are not shares of people and should not be added into a pie or averaged into a single household forecast.'},
  {...source,id:'expectations-quarterly-history',type:'line',evidence:'Official survey results',title:'Compare each expectation horizon across the same eight survey quarters',unit:'percent',unitLabel:'Published interpolated median (%) · 2024 Q4–2026 Q3',yMin:0,yMax:.05,xLabel:'Survey quarter · labels show YYQx',xTicks:[{value:0,label:'24Q4'},{value:4,label:'25Q4'},{value:7,label:'26Q3'}],series:horizonSeries.map(([key,label],j)=>({name:label,dash:j===1,rows:observations.map((r,x)=>({x,label:r.quarter,value:r[key]/100}))})),note:'Each point is one published quarterly summary. Lines connect quarter positions, not daily observations or the path of an individual respondent. The series share one percent scale and the same source vintage. The data table retains full quarter labels.'},
  {...source,id:'expectations-quarter-change',type:'signedbar',evidence:'Derived from published survey medians',title:'The latest quarterly differences are percentage points, not percentage changes',unit:'pp',unitLabel:'2026 Q3 minus 2026 Q2 · percentage points',rows:horizonSeries.map(([key,label])=>({label:label,value:(last[key]-prior[key])/100})),note:'Subtract the two published percentage levels. A change of 0.52 percentage points is a difference between levels, not a 0.52% relative change or a change in the price level. These descriptive differences do not establish statistical significance, individual opinion changes or a causal explanation.'},
  {id:'expectations-independent-cost',type:'line',title:'Use a separately chosen price-growth assumption for a household cost scenario',unit:'money',unitLabel:'CAD for one year’s cost · not cumulative spending',xLabel:'Scenario years from today',series:[series('Annual cost at the future date','future'),series('Starting annual cost · reference','current',true)],note:'This hypothetical curve does not compound a survey median. Each future point is current annual cost × (1 + independently entered price growth)^year. The reference stays at its starting nominal amount. No extra consumption, funding or investment result is inferred.'},
  {id:'expectations-cost-scenarios',type:'heatmap',title:'Price scenarios can test a range without declaring one survey answer a forecast',unit:'money',columns:['5 yrs','10 yrs','15 yrs','20 yrs'],rows:[0,2,4,6].map(rate=>({label:rate+'% prices',values:[5,10,15,20].map(year=>i.expectCost*(1+rate/100)**year)})),note:'Rows and columns replace annual price growth and the horizon. Only the entered starting annual cost is retained. Every cell is an annual cost at its stated endpoint. These alternative scenarios have no assigned probabilities and are independent of all CSCE medians.'}
 ]};
}
